import Icons from './utils/Icons.js';
import ComponentFactory from './ComponentFactory.js';
import Modale from './components/Modale.js';

class Main {
  constructor() {
    this.init();
  }

  init() {
    // On ajoute une classe sur le html
    // pour qu'on puisse savoir si le JavaScript est
    // supporté dans notre css
    document.documentElement.classList.add('has-js');

    new ComponentFactory();
    new Modale();
    Icons.load();
    this.loading();
  }

  loading() {
    event.preventDefault();
    target.scrollIntoView({ behavior: 'smooth' });
    console.log('PLEASE CLOSE');
    window.addEventListener('load', () => {
      const loadingScreen = document.querySelector('.loading-screen');

      // Laisse l'image tourner pendant 2 secondes
      setTimeout(() => {
        loadingScreen.classList.add('fade-out');

        // Supprime complètement l'écran après le fade
        setTimeout(() => {
          loadingScreen.remove();
        }, 1000);
      }, 2000);
    });
  }
}
new Main();
